class Solution {
    public boolean isCousins(TreeNode root,int x,int y){
        Queue<TreeNode[]> queue=new ArrayDeque<>();
        queue.offer(new TreeNode[]{
            root,null
        });
        while(!queue.isEmpty()){
            TreeNode parentX=null,parentY=null;
            for(int size=queue.size();size>0;size--){
                TreeNode[] entry=queue.poll();
                TreeNode node=entry[0],parent=entry[1];
                if(node.val==x)parentX=parent;
                if(node.val==y)parentY=parent;
                if(node.left!=null)queue.offer(new TreeNode[]{
                    node.left,node
                });
                if(node.right!=null)queue.offer(new TreeNode[]{
                    node.right,node
                });
            }
            if(parentX!=null||parentY!=null)return parentX!=null&&parentY!=null&&parentX!=parentY;
        }
        return false;
    }
}

