class Solution {
    fun isCousins(root:TreeNode?,x:Int,y:Int):Boolean{
        root?:return false;
        val queue=java.util.ArrayDeque<Pair<TreeNode,TreeNode?>>();
        queue.addLast(root to null);
        while(queue.isNotEmpty()){
            var parentX:TreeNode?=null;
            var parentY:TreeNode?=null;
            repeat(queue.size){
                val (node,parent)=queue.removeFirst();
                if(node.`val`==x)parentX=parent;
                if(node.`val`==y)parentY=parent;
                if(node.left!=null)queue.addLast(node.left!! to node);
                if(node.right!=null)queue.addLast(node.right!! to node)
            };
            if(parentX!=null||parentY!=null)return parentX!=null&&parentY!=null&&parentX!==parentY
        };
        return false
    }
}

